    }

    event.tasksAfterSend.add(
      Runnable {
        scheduler.runSync(
          viewer,
          Runnable {
            val activeViewer = viewerResolver(viewer.uniqueId) ?: return@Runnable
            coordinator.removeTrackedEntities(activeViewer.uniqueId, entityIds)
          },
        )
      }
